INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (5, 'Benang overlock sering putus', 'Benang jarum atau looper sering putus saat proses menjahit.', 'Pemasangan benang tidak sesuai jalur, tegangan benang terlalu tinggi, jarum DC×27 tidak sesuai atau kondisi jarum sudah buruk.', 'Periksa seluruh jalur benang, sesuaikan tegangan dengan material, dan pastikan jarum DC×27 terpasang dengan benar serta tidak bengkok atau tumpul.', 'Matikan mesin sebelum mengganti jarum atau melakukan penyesuaian pada jalur benang.', 'Panduan troubleshooting umum JUKI MO-6700S');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (5, 'Jahitan overlock loncat atau tidak terbentuk', 'Stitch tidak terbentuk sempurna dan terdapat bagian jahitan yang terlewat.', 'Jarum bengkok atau tumpul, pemasangan jarum kurang tepat, timing looper dan jarum tidak sesuai, atau jalur benang bermasalah.', 'Periksa dan ganti jarum DC×27 bila diperlukan. Pastikan pemasangan jarum dan jalur benang benar. Jika masalah tetap terjadi, periksa timing looper oleh teknisi.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa area jarum atau looper.', 'Panduan troubleshooting umum JUKI MO-6700S');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (5, 'Jahitan mengerut atau bergelombang', 'Tepi kain mengerut, bergelombang, atau hasil overlock tidak rata.', 'Differential feed tidak sesuai dengan karakter material atau tekanan presser foot dan tegangan benang kurang tepat.', 'Sesuaikan differential feed secara bertahap sesuai material. Gunakan rasio gathering atau stretching sesuai kebutuhan material.', 'Matikan mesin sebelum melakukan penyetelan mekanisme feeding.', 'Data spesifikasi differential feed JUKI MO-6700S');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (5, 'Tepi kain tidak terpotong atau tidak rapi', 'Pisau overlock tidak memotong tepi kain dengan baik atau hasil potongan tidak rata.', 'Kondisi pisau kurang baik, posisi material tidak tepat, atau mekanisme pemotong mengalami gangguan.', 'Periksa kondisi dan posisi pisau serta pastikan material masuk dengan stabil. Jika pisau tumpul atau mekanisme bermasalah, lakukan penggantian atau pemeriksaan oleh teknisi.', 'Matikan mesin dan lepaskan sumber listrik sebelum menyentuh area pisau.', 'Panduan pemeriksaan umum mesin overlock JUKI');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (5, 'Differential feed tidak bekerja normal', 'Material tertarik terlalu banyak, terlalu sedikit, atau feeding tidak stabil.', 'Pengaturan differential feed tidak sesuai, mekanisme feed mengalami gangguan, atau material tidak sesuai dengan penyetelan.', 'Periksa pengaturan differential feed dan lakukan penyetelan bertahap sesuai kebutuhan material.', 'Matikan mesin sebelum memeriksa mekanisme feed.', 'Data spesifikasi differential feed JUKI MO-6700S');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (5, 'Panjang jahitan tidak sesuai', 'Panjang stitch aktual berbeda dari pengaturan atau hasil jahitan tidak konsisten.', 'Pengaturan stitch length berubah, mekanisme feed tidak bekerja normal, atau kondisi material memengaruhi feeding.', 'Periksa pengaturan panjang jahitan dan kondisi mekanisme feed. Sesuaikan dengan subclass mesin dan material yang digunakan.', 'Matikan mesin sebelum memeriksa atau menyetel mekanisme feed.', 'Data spesifikasi stitch length JUKI MO-6700S');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (5, 'Pelumasan otomatis tidak normal', 'Mesin terdengar kasar, panas berlebih, atau gerakan bagian mesin terasa tidak lancar.', 'Sistem pelumasan otomatis terganggu atau kondisi oli tidak sesuai.', 'Periksa sistem pelumasan otomatis dan kondisi oli sesuai prosedur perawatan mesin. Jika pelumasan tidak berjalan normal, hentikan pengoperasian dan lakukan pemeriksaan teknisi.', 'Matikan mesin sebelum memeriksa sistem pelumasan.', 'Data spesifikasi lubrication JUKI MO-6700S');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (5, 'Motor atau putaran mesin tidak normal', 'Putaran mesin tidak stabil, motor kehilangan tenaga, atau respons mesin tidak sesuai.', 'Gangguan pada motor, koneksi listrik, sistem penggerak, atau beban mekanis mesin.', 'Periksa koneksi motor dan kondisi sistem penggerak. MO-6700S menggunakan motor 400 W atau 550 W tergantung konfigurasi.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa motor atau koneksi kelistrikan.', 'Data spesifikasi motor JUKI MO-6700S dan panduan pemeriksaan umum');
